import math

def perfect_squares(a, b):
    lower = min(a, b)
    upper = max(a, b)

    if lower == upper:
        return []

    if upper < 0:
        return []

    max_n = math.isqrt(upper)
    result = []

    for n in range(0, max_n + 1):
        square = n * n
        if square >= lower and square <= upper:
            result.append(square)

    return result

