from typing import List

def factorize(n: int) -> List[int]:
    original_n = n
    factors = []
    divisor = 2
    while n > 1:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1
    if original_n == 2:
        factors.append(1)
    return factors

