def match_parens(lst):
    a, b = lst
    total_open = a.count('(') + b.count('(')
    total_close = a.count(')') + b.count(')')

    if total_open != total_close:
        return 'No'

    def is_balanced(s):
        balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    if is_balanced(a + b):
        return 'Yes'
    if is_balanced(b + a):
        return 'Yes'
    return 'No'
