def get_total_number_of_sequences(m, n):
    if n == 1:
        return m
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count(pos, prev):
        if pos == n:
            min_val = 2 * prev
            if min_val > m:
                return 0
            else:
                return m - min_val + 1
        else:
            if pos == 1:
                min_val = 1
            else:
                min_val = 2 * prev
            if min_val > m:
                return 0
            total = 0
            for next_val in range(min_val, m + 1):
                total += count(pos + 1, next_val)
            return total

    return count(1, 0)
