def cal_sum(n):
    if n < 0:
        return 5
    if n == 0:
        return 3
    elif n == 1:
        return 3
    elif n == 2:
        return 5
    sum_total = 3 + 0 + 2  # P(0) + P(1) + P(2)
    p_prev3, p_prev2, p_prev1 = 3, 0, 2  # P(0), P(1), P(2)
    for i in range(3, n + 1):
        current = p_prev1 + p_prev3
        sum_total += current
        p_prev3, p_prev2, p_prev1 = p_prev2, p_prev1, current
    return sum_total
